/// Computes the n-th Fibonacci number using an iterative approach.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(fib(0), 0);
/// assert_eq!(fib(1), 1);
/// assert_eq!(fib(2), 1);
/// assert_eq!(fib(3), 2);
/// assert_eq!(fib(4), 3);
/// assert_eq!(fib(5), 5);
/// assert_eq!(fib(6), 8);
/// assert_eq!(fib(7), 13);
/// assert_eq!(fib(8), 21);
/// assert_eq!(fib(9), 34);
/// ```
fn fib(n: u32) -> u64 {
    if n == 0 {
        return 0;
    } else if n == 1 {
        return 1;
    }

    let mut a = 0;
    let mut b = 1;
    let mut next = 0;

    for _ in 2..=n {
        next = a + b;
        a = b;
        b = next;
    }

    next
}

// Function to check the correctness of the fib function
fn check_fib() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(2), 1);
    assert_eq!(fib(3), 2);
    assert_eq!(fib(4), 3);
    assert_eq!(fib(5), 5);
    assert_eq!(fib(6), 8);
    assert_eq!(fib(7), 13);
    assert_eq!(fib(8), 21);
    assert_eq!(fib(9), 34);
    println!("All tests passed!");
}

