/// Checks if a given string is a palindrome, ignoring case and non-letter/digit characters.
/// An empty string is considered a palindrome.
///
/// # Examples
///
/// ```
/// assert_eq!(is_palindrome("A man, a plan, a canal, Panama"), true);
/// assert_eq!(is_palindrome("No lemon, no melon"), true);
/// assert_eq!(is_palindrome("Hello, World!"), false);
/// assert_eq!(is_palindrome("Was it a car or a cat I saw?"), true);
/// assert_eq!(is_palindrome("Was it a car or a cat I saw?"), false);
/// ```
fn is_palindrome(s: &str) -> bool {
    let cleaned_s: String = s.chars().filter(|c| c.is_alphabetic() || c.is_digit()).collect();
    cleaned_s == cleaned_s.chars().rev().collect()
}

// Function to check the correctness of the `is_palindrome` function
fn check_palindrome() {
    assert_eq!(is_palindrome("A man, a plan, a canal, Panama"), true);
    assert_eq!(is_palindrome("No lemon, no melon"), true);
    assert_eq!(is_palindrome("Hello, World!"), false);
    assert_eq!(is_palindrome("Was it a car or a cat I saw?"), true);
    assert_eq!(is_palindrome("Was it a car or a cat I saw?"), false);
}

