/// Returns every prime number less than or equal to n, in increasing order.
///
/// # Examples
///
/// ```
/// assert_eq!(primes_up_to(10), vec![2, 3, 5, 7]);
/// assert_eq!(primes_up_to(20), vec![2, 3, 5, 7, 11, 13, 17, 19]);
/// ```
fn primes_up_to(n: u32) -> Vec<u32> {
    let mut primes = Vec::new();
    let mut is_prime = vec![true; n + 1];
    is_prime[0] = is_prime[1] = false;

    for i in 2..=((n as f64).sqrt() as u32) {
        if is_prime[i] {
            for j in (i * i)..=n {
                is_prime[j] = false;
            }
        }
    }

    for i in 2..=n {
        if is_prime[i] {
            primes.push(i);
        }
    }

    primes
}

// Check function to verify the correctness of the primes_up_to function.
fn check_primes_up_to() {
    assert_eq!(primes_up_to(10), vec![2, 3, 5, 7]);
    assert_eq!(primes_up_to(20), vec![2, 3, 5, 7, 11, 13, 17, 19]);
    assert_eq!(primes_up_to(1), vec![2]);
    assert_eq!(primes_up_to(21), vec![2, 3, 5, 7, 11, 13, 17, 19]);
    println!("All tests passed!");
}

