/// Calculate the greatest common divisor (GCD) of two numbers using the Euclidean algorithm.
/// The GCD of two numbers is the largest positive integer that divides both of them without leaving a remainder.
/// If the GCD is 1, then the numbers are coprime.
///
/// # Examples
///
/// ```
/// assert_eq!(gcd(0, 5), 5);
/// assert_eq!(gcd(100, 200), 100);
/// assert_eq!(gcd(17, 13), 1);
/// ```
fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        return a;
    }
    gcd(b, a % b)
}

// Function to check the correctness of the gcd function
fn check_gcd() {
    assert_eq!(gcd(0, 5), 5);
    assert_eq!(gcd(100, 200), 100);
    assert_eq!(gcd(17, 13), 1);
    println!("All tests passed!");
}

