use std::str::SplitWhitespace;

/// Reverses the words in a given string.
///
/// # Examples
///
/// ```
/// assert_eq!(reverse_words(String::from("hello world")), String::from("dlrow olleh"));
/// ```
fn reverse_words(s: &str) -> String {
    let mut words: Vec<&str> = s.split_whitespace().collect();
    words.reverse();
    words.join(" ")
}

// Function to check the correctness of the reverse_words function
