    assert_eq!(reverse_words(String::from("hello world")), String::from("dlrow olleh"));
    assert_eq!(reverse_words(String::from("rust programming")), String::from("gnimmargorp tsiht"));
    assert_eq!(reverse_words(String::from("")), String::from(""));
    println!("All tests passed!");
}

