/// Determines if two strings are anagrams of each other, ignoring case and spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(is_anagram("listen", "silent"), true);
/// assert_eq!(is_anagram("hello", "billion"), false);
/// assert_eq!(is_anagram("Dormitory", "dirty room"), true);
/// assert_eq!(is_anagram("Conversation", "Voices rant on"), true);
/// assert_eq!(is_anagram("A gentleman", "Elegant man"), true);
/// assert_eq!(is_anagram("Conversation", "Voices rant on"), false);
/// ```
fn is_anagram(a: &str, b: &str) -> bool {
    // Remove spaces and convert to lowercase for case-insensitive comparison
    let a = a.replace(" ", "").to_lowercase();
    let b = b.replace(" ", "").to_lowercase();

    // If lengths are not equal, they cannot be anagrams
    if a.len() != b.len() {
        return false;
    }

    // Create frequency maps for both strings
    let mut freq_a = [0; 26];
    let mut freq_b = [0; 26];

    for c in a.chars() {
        freq_a[c as usize - 'a'] += 1;
    }

    for c in b.chars() {
        freq_b[c as usize - 'a'] += 1;
    }

    // Compare frequency maps
    for i in 0..26 {
        if freq_a[i] != freq_b[i] {
            return false;
        }
    }

    true
}

