/// Finds the largest sum of a contiguous subarray in a given slice of integers.
/// If the slice is empty, returns 0.
///
/// # Examples
///
/// ```
/// assert_eq!(max_subarray(&[1, -2, 3, -4, 5]), 9);
/// assert_eq!(max_subarray(&[-1, -2, -3]), 0);
/// assert_eq!(max_subarray(&[]), 0);
/// ```
fn max_subarray(v: &[i64]) -> i64 {
    if v.is_empty() {
        return 0;
    }

    let mut max_so_far = v[0];
    let mut min_so_far = v[0];
    let mut current_max = v[0];

    for &num in &v[1..] {
