/// Shifts each ASCII letter forward by shift positions in the alphabet, wrapping around and keeping its case.
/// Other characters remain as they are.
///
/// # Examples
///
/// ```
/// assert_eq!(caesar("hello", 3), "lipps");
/// assert_eq!(caesar("world", 5), "asdfghjkl");
/// assert_eq!(caesar("rust", 1), "tus");
/// ```
fn caesar(s: &str, shift: u8) -> String {
    let mut result = String::new();
    for c in s.chars() {
        if c.is_ascii_alphabetic() {
            let base = if c.is_uppercase() { 65 } else { 97 };
            let shifted = ((c as u8 - base + shift) % 26) + base;
            result.push((shifted as u8 + base) as char);
        } else {
            result.push(c);
        }
    }
    result
}

