use std::str::SplitWhitespace;

/// Capitalizes the first letter of each word in a given string.
/// Words are considered to be separated by single spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(capitalize_words(String::from("hello world")), String::from("Hello World"));
/// assert_eq!(capitalize_words(String::from("rust programming")), String::from("Rust Programming"));
/// ```
fn capitalize_words(s: &str) -> String {
    let mut words: Vec<&str> = s.split_whitespace().collect();
    let mut capitalized_words: Vec<String> = words.into_iter().map(|word| {
        let mut capitalized_word = word.to_string();
        capitalized_word.chars().next().map(|c| {
            if c.is_lowercase() {
                c.to_uppercase()
            } else {
                c
            }
        }).collect();
        capitalized_word
    }).collect();
    capitalized_words.join(" ");
}

// Function to check the correctness of the capitalize_words function
fn check() {
    assert_eq!(capitalize_words(String::from("hello world")), String::from("Hello World"));
    assert_eq!(capitalize_words(String::from("rust programming")), String::from("Rust Programming"));
    assert_eq!(capitalize_words(String::from("rust")), String::from("Rust"));
    assert_eq!(capitalize_words(String::from("")), String::from(""));
    println!("All tests passed!");
}

