/// Transpose a rectangular matrix given as rows.
/// An empty matrix returns an empty matrix.
///
/// # Examples
///
/// ```
/// assert_eq!(transpose(vec![]), Vec::<Vec<i32>>::new());
/// assert_eq!(transpose(vec![vec![1, 2], vec![3, 4]]), vec![
///     vec![1, 3],
///     vec![2, 4]
/// ]);
/// ```
fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    if m.is_empty() {
        return Vec::new();
    }

    let mut transposed = Vec::new();
    for i in 0..m.len() {
        let mut row = Vec::new();
        for j in 0..m.len() {
            row.push(m[j][i]);
        }
        transposed.push(row);
    }
    transposed
}

// Check function to verify the correctness of the transpose function
fn check_transpose() {
    assert_eq!(transpose(vec![]), Vec::<Vec<i32>>::new());
    assert_eq!(transpose(vec![vec![1, 2], vec![3, 4]]), vec![
        vec![1, 3],
        vec![2, 4]
    ]);
    assert_eq!(transpose(vec![vec![5, 6], vec![7, 8]]), vec![
        vec![5, 7],
        vec![6, 8]
    ]);
    println!("All tests passed!");
}

