/// Parses a colour written as "#rrggbb" (hexadecimal, any case) and returns a tuple of RGB values.
/// If the input is not a valid hexadecimal color, returns None.
///
/// # Examples
///
/// ```
/// assert_eq!(hex_to_rgb("#ff0000"), Some((255, 0, 0)));
/// assert_eq!(hex_to_rgb("#123456"), Some((123, 456, 89)));
/// assert_eq!(hex_to_rgb("#000000"), None);
/// assert_eq!(hex_to_rgb("#1234567890"), None);
/// ```
fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 7 {
        return None;
    }

    let mut r = 0;
    let mut g = 0;
    let mut b = 0;

    for (i, c) in s.chars().enumerate() {
        match c {
            '0'..='9' => r = r * 16 + c as u8 - '0' as u8,
            'a'..='f' => g = g * 16 + c as u8 - 'a' as u8,
            'A'..='F' => b = b * 16 + c as u8 - 'A' as u8,
            _ => return None,
        }
    }

    Some((r, g, b))
}

