/// Rotates a slice `v` to the left by `k` positions.
/// If `k` is greater than the length of `v`, returns an empty vector.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(rotate_left(vec![1, 2, 3], 2), vec![3, 1, 2]);
/// assert_eq!(rotate_left(vec![1, 2, 3], 5), vec![1, 2, 3]);
/// assert_eq!(rotate_left(vec![1, 2, 3], 0), vec![1, 2, 3]);
/// assert_eq!(rotate_left(vec![1, 2, 3], 10), vec![1, 2, 3]);
/// ```
fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    if k >= v.len() {
        return Vec::new();
    }
    let mut rotated = Vec::with_capacity(v.len());
    rotated.extend_from_slice(&v[k..]);
    rotated.extend_from_slice(&v[..k]);
    rotated
}

// Check function to verify the correctness of the rotate_left function
