/// Parses a string of key-value pairs separated by semicolons into a map.
/// Pairs are separated by ";", and each pair is "key=value".
/// Pairs without "=" are ignored.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_kv("a=1;b=two"), HashMap::from([(String::from("a"), String::from("1")), (String::from("b"), String::from("two"))]));
/// assert_eq!(parse_kv("a=1; b=two; c=three"), HashMap::from([(String::from("a"), String::from("1")), (String::from("b"), String::from("two")), (String::from("c"), String::from("three"))]));
/// assert_eq!(parse_kv("a=1; b=two; c=three; d=four"), HashMap::from([(String::from("a"), String::from("1")), (String::from("b"), String::from("two")), (String::from("c"), String::from("three")), (String::from("d"), String::from("four"))]));
/// ```
fn parse_kv(s: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    let mut current_pair = String::new();

    for c in s.chars() {
        if c == ';' {
            if current_pair.is_empty() {
                continue;
