/// Calculates the running sum of a vector of integers.
///
/// # Examples
///
/// ```
/// assert_eq!(running_sum(vec![1, 2, 3]), vec![1, 3, 6]);
/// assert_eq!(running_sum(vec![5, 3, 2, 8]), vec![5, 8, 10, 18]);
/// ```
fn running_sum(v: &[i32]) -> Vec<i32> {
    let mut running_sum = Vec::new();
    let mut current_sum = 0;

    for &value in v {
        current_sum += value;
        running_sum.push(current_sum);
    }

    running_sum
}

// Function to check the correctness of the running_sum function
fn check_running_sum() {
    assert_eq!(running_sum(vec![1, 2, 3]), vec![1, 3, 6]);
    assert_eq!(running_sum(vec![5, 3, 2, 8]), vec![5, 8, 10, 18]);
    assert_eq!(running_sum(vec![]), Vec::<i32>::new());
    assert_eq!(running_sum(vec![10]), vec![10]);
    println!("All tests passed!");
}

