/// Counts the number of times a character appears in a string.
///
/// # Examples
///
/// ```
/// assert_eq!(count_char("hello", 'h'), 2);
/// assert_eq!(count_char("rust", 'r'), 2);
/// ```
fn count_char(s: &str, c: char) -> usize {
    s.chars().filter(|&c| c == c).count()
}

